package dev.mesbase;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import dev.mesbase.common.utils.html.RichTextSanitizer;
class SourceMigrationSecurityTest {
 @Test void richTextRetainsSourceFormattingWithoutExecutableMarkup(){String html=RichTextSanitizer.clean("<h2>标题</h2><ol><li data-list='ordered'>内容</li></ol><p class='ql-align-center evil' style='color:rgb(1, 2, 3);background-image:url(https://invalid.example)'>文本</p><script>evil()</script><img src='javascript:evil()' onerror='evil()'><a href='javascript:evil()'>链接</a>");assertTrue(html.contains("<h2>标题</h2>"));assertTrue(html.contains("data-list=\"ordered\""));assertTrue(html.contains("ql-align-center"));assertFalse(html.contains("javascript:"));assertFalse(html.contains("<script"));assertFalse(html.contains("background-image"));assertFalse(html.contains("onerror"));assertFalse(html.contains("evil()"));}
 @Test void mediaReferencesAreCanonicalAndNeverPublicUrls(){String id="11111111-1111-4111-8111-111111111111";String html=RichTextSanitizer.clean("<img data-file-id='"+id+"' data-resource='notice-media' src='https://invalid.example/private'>");assertTrue(html.contains("/api/platform/files/"+id+"/content?resource=notice-media"));assertFalse(html.contains("invalid.example"));assertEquals("",RichTextSanitizer.clean("<img src='https://invalid.example/image.png'>"));}
 @Test void textAndSourcePermissionNamesArePreserved(){assertEquals("A & B",RichTextSanitizer.clean("A & B"));assertDoesNotThrow(()->new dev.mesbase.core.security.Permission("system:user:resetPwd"));assertNull(new dev.mesbase.common.core.domain.entity.SysRole().getKind());}
}
